func standardSObjectStubFieldsFor(objectName string) (map[string]Field, bool) {
	fields, ok := standardSObjectStubFieldData[objectName]
	if ok {
		return fields, true
	}
	initStandardSObjectStubLookupCache()
	fields, ok = standardSObjectStubLookupCache.fieldsByLC[standardObjectLookupKey(objectName)]
	return fields, ok
}

func standardSObjectStubNames() []string {
	names := make([]string, 0, len(standardSObjectStubFieldData))
	for name := range standardSObjectStubFieldData {
		names = append(names, name)
	}
	return names
}

